import usePumpTokenListStore from '@/store/pumpTokenList'
import useTradeTokenStore from '@/store/tradeToken'
import { queryTokenListPath } from '@/type/api'
import { CacheClmmInfo, PumpToken } from '@/type/pump'
import { PumpUtils } from '@/utils/pumpUtils'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { TickMath, extractStructTagFromType } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { BondingCurveStatus, MEMEDecimal } from '@cetusprotocol/cetus-sui-pump-sdk'
import { SUI_DECIMALS } from '@mysten/sui/utils'
import BN from 'bn.js'
import { useEffect, useState } from 'react'
import { usePumpApiDomain } from '../common/usePumpApiDomain'

export function useGetPumpToken(coinType?: string) {
  const { pumpTokenList } = usePumpTokenListStore()
  const { pumpSdk, clmmSdk } = useInitSDK()
  const [loading, setLoading] = useState<boolean>()
  const { fetchTokenInfo } = useGetToken()
  const { currentToken, setCurrentToken, resetCurrentToken } = useTradeTokenStore()
  const { cacheClmmInfo, setCacheClmmInfo } = usePumpTokenListStore()
  const { fetchGetByApi } = usePumpApiDomain()

  const fetchPumpTokenFromApi = async (coin_type = coinType) => {
    if (!coin_type) {
      setLoading(false)
      return
    }

    const params = new URLSearchParams({ page: String(1), page_size: String(10) })

    params.set('query_filter_value', coin_type)
    params.set('query_filter_type', 'coin_type')

    try {
      const response = await fetchGetByApi(`${queryTokenListPath}?${params.toString()}`)
      const list = response.tokenVolumes

      let info
      if (list) {
        info = list.find((item: any) => extractStructTagFromType(item.coin_type).full_address === extractStructTagFromType(coin_type).full_address)
      }
      console.log('🚀 ~ file: useGetPumpToken.ts:41 ~ fetchPumpToken ~ info:', {
        info,
        coin_type
      })
      if (info) {
        info = PumpUtils.formatPumpToken(info, currentToken?.token_info_id === info.token_info_id ? currentToken : undefined)
        setCurrentToken(info)
      }
      fetchPumpTokenFromContract(coin_type, info)
    } catch (error) {
      console.log('🚀 ~ file: useGetPumpToken.ts:36 ~ fetchPumpToken ~ error:', error)
      fetchPumpTokenFromContract(coin_type)
    } finally {
      setLoading(false)
    }
  }

  /**
   * 从合约获取数据
   * @param coinType
   * @param info
   */
  const fetchPumpTokenFromContract = async (coinType: string, originInfo?: PumpToken) => {
    let updatedInfo: PumpToken | undefined = undefined
    if (originInfo) {
      // 获取BondingCurve 池子数据， 更新原始originInfo 数据
      if (originInfo.status < BondingCurveStatus.LP_BURNED) {
        const contractInfo = await pumpSdk.pumpModule.getBondingCurveById(originInfo.token_info_id)
        updatedInfo = PumpUtils.parseBondingCurve(contractInfo, originInfo)
      } else {
        updatedInfo = { ...originInfo }
      }
    } else {
      //  获取BondingCurve 池子数据, 完成全新数据组装
      const coinInfo = await fetchTokenInfo(coinType!)
      if (coinInfo) {
        const contractInfo = await pumpSdk.pumpModule.getBondingCurveByCoinType(coinType)
        updatedInfo = PumpUtils.parseBondingCurve(contractInfo, undefined, coinInfo)
      }
    }

    // 如果已迁移到clmm，则需要获取clmm 相关数据
    if (updatedInfo && updatedInfo.status >= BondingCurveStatus.MIGRATED) {
      let clmmPoolId: string | undefined = updatedInfo.TokenDetail.clmm_pool
      if (!clmmPoolId || clmmPoolId.length === 0) {
        clmmPoolId = await pumpSdk.pumpModule.getClmmPoolId(updatedInfo.token_info_id, updatedInfo.status === BondingCurveStatus.LP_BURNED)
      }
      if (clmmPoolId) {
        updatedInfo.TokenDetail.clmm_pool = clmmPoolId
        const pool = (await clmmSdk.Pool.getPool(clmmPoolId)) || cacheClmmInfo[clmmPoolId]
        if (pool) {
          updatedInfo.current_sqrt_price = pool.current_sqrt_price.toString()
          updatedInfo.liquidity = pool.liquidity.toString()
          updatedInfo.coin_a = pool.coinAmountA.toString()
          updatedInfo.coin_b = pool.coinAmountB.toString()
          const current_ui_price = TickMath.sqrtPriceX64ToPrice(new BN(updatedInfo.current_sqrt_price), MEMEDecimal, SUI_DECIMALS).toString()
          updatedInfo.current_ui_price = current_ui_price

          const info: CacheClmmInfo = {
            pool_id: clmmPoolId,
            current_ui_price: current_ui_price,
            current_sqrt_price: updatedInfo.current_sqrt_price,
            liquidity: updatedInfo.liquidity,
            last_update_time: new Date().getTime(),
            coin_a: updatedInfo.coin_a,
            coin_b: updatedInfo.coin_b
          }

          setCacheClmmInfo(info)
        }
      }
    }

    console.log('🚀 ~ file: useGetPumpToken.ts:101 ~ fetchPumpTokenFromContract ~ updatedInfo:', updatedInfo)
    if (updatedInfo) {
      // 数据更新完成 重新赋值
      setCurrentToken({ ...updatedInfo })
    }
  }

  useEffect(() => {
    if (coinType) {
      setLoading(true)
      // 优先缓存获取
      const info = pumpTokenList.find(item => item.coin_type === coinType)
      setCurrentToken(info)
      if (info) {
        setLoading(false)
        // 从合约加载数据
        fetchPumpTokenFromContract(info.coin_type, info)
      } else {
        // 从Api接口加载数据
        fetchPumpTokenFromApi(coinType)
      }
    }
  }, [coinType])

  const refreshPumpToken = (coinType: string) => {
    setLoading(true)
    fetchPumpTokenFromApi(coinType)
  }

  return {
    currentToken,
    loading,
    refreshPumpToken
  }
}
