import { useGetPumpToken } from '@/hook/pump/useGetPumpToken'
import useTradeTokenStore from '@/store/tradeToken'
import { useAccountBalance, useInterval } from '@cetus/hooks'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { useEffect, useMemo, useState } from 'react'
import { useParams } from 'react-router-dom'
import H5Trade from './H5Trade'
import PCTrade from './PCTrade'

function Trade() {
  const { id } = useParams()
  const { loading, refreshPumpToken } = useGetPumpToken(id)
  const { currentToken, setCurrentToken, resetCurrentToken } = useTradeTokenStore()
  const { isApp } = useWindowWidth()
  const [refreshFlag, setRefreshFlag] = useState<number>(0)
  const { fetchAccountBalance } = useAccountBalance()
  useEffect(() => {
    return () => {
      resetCurrentToken()
    }
  }, [])

  const status = useMemo(() => {
    if (currentToken) {
      return currentToken.status
    }
    return BondingCurveStatus.RAISING
  }, [currentToken])

  const handleRefresh = (timestamp = new Date().getTime()) => {
    // 控制其他主件刷新
    setRefreshFlag(timestamp)
    if (id) {
      // 刷新池子信息
      refreshPumpToken(id)
      // 刷新余额
      fetchAccountBalance()
    }
  }

  useInterval({
    interval: 20 * 1000, // 20,秒
    callback: (timestamp: number) => {
      handleRefresh(timestamp)
    }
  })

  const props = {
    handleRefresh,
    loading,
    currentToken,
    refreshFlag,
    status
  }

  return isApp ? <H5Trade {...props} /> : <PCTrade {...props} />
}

export default Trade
