import { PumpToken } from '@/type/pump'
import { create, StateCreator } from 'zustand'

interface TradeTokenState {
  currentToken?: PumpToken
  setCurrentToken: (pumpToken?: PumpToken) => void
  resetCurrentToken: () => void
}

const store: StateCreator<TradeTokenState> = (set, get) => ({
  currentToken: undefined,
  setCurrentToken: (pumpToken?: PumpToken) => {
    set(() => ({
      currentToken: pumpToken
    }))
  },
  resetCurrentToken: () => {
    set(() => ({
      currentToken: undefined
    }))
  }
})

const useTradeTokenStore = create(store)
export default useTradeTokenStore
