import { useTokenHolder } from '@/hook/pump/useTokenHolder'
import { AddressUnderline } from '@cetus/design'
import Block from '@cetus/design/src/components/common/Block'
import { NoData } from '@cetus/ui-kit'
import { HStack, Skeleton, Text, VStack } from '@chakra-ui/react'
import { useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'

function HolderDistribution({ loading, refreshFlag }: { loading?: boolean; refreshFlag: number }) {
  const { id } = useParams()
  const { holderTokenList, holderLoading, fetchTokenHolderList } = useTokenHolder(id)

  useEffect(() => {
    if (refreshFlag && id) {
      fetchTokenHolderList(id)
    }
  }, [refreshFlag])

  const navigate = useNavigate()

  return (
    <Block>
      <HStack justify="space-between" mb="20px">
        <Text color="text_caption" fontSize="16px">
          Holder Distribution
        </Text>
        {/* {holderTokenList?.length && (
          <HStack>
            <Icon xlinkHref="#icon-icon_people" svgHover="text_paragraph" />
            <Skeleton display="inline-block" lineHeight="1" isLoaded={!loading && !holderLoading}>
              <Text color="text_caption">{holderTokenList?.length}</Text>
            </Skeleton>
          </HStack>
        )} */}
      </HStack>
      {(!holderTokenList || !holderTokenList.length) && !holderLoading ? (
        <NoData type="nodata" text="No holders" border="none" />
      ) : (
        <VStack w="100%" gap="20px">
          {loading || holderLoading ? (
            <>
              {[1, 2, 3].map((item, index) => (
                <HStack w="100%" justify="space-between" key={index}>
                  <Skeleton flex="0 0 200px" />
                  <Skeleton />
                </HStack>
              ))}
            </>
          ) : (
            holderTokenList?.map((token, index) => (
              <HStack w="100%" justify="space-between" key={token.holderAddress}>
                <AddressUnderline
                  address={token.holderAddress}
                  color="text_caption"
                  fontSize="14px"
                  onClickLink={() => {
                    // 钱包地址
                    navigate(`/profile/${token.holderAddress}`)
                  }}
                />
                <Text color="text_caption">{token?.percentage}</Text>
              </HStack>
            ))
          )}
        </VStack>
      )}
    </Block>
  )
}

export default HolderDistribution
