import { Box } from '@chakra-ui/react'
import { useState } from 'react'
import ChartLoading from './ChartLoading'

type CurrentChartType = {
  tokenAddress: string
  poolAddress: string
}
export default function CurrentChart({ tokenAddress, poolAddress }: CurrentChartType) {
  const [isLoading, setLoading] = useState(true)
  return (
    <Box w="100%" h="100%" position="relative">
      {(isLoading || !tokenAddress || !poolAddress) && <ChartLoading />}
      <iframe
        id="geckoterminal-embed"
        className="frame"
        height="100%"
        width="100%"
        title="GeckoTerminal Embed"
        frameBorder="0"
        allow="clipboard-write"
        allowFullScreen
        src={`https://birdeye.so/tv-widget/${tokenAddress}/${poolAddress}?chain=sui`}
        onLoad={() => {
          setLoading(false)
        }}
      />
    </Box>
  )
}
