import { queryTokenHoldersByCoinTypePath } from '@/type/api'
import { TokenHolder } from '@/type/pump'
import { useEffect, useState } from 'react'
import { usePumpApiDomain } from '../common/usePumpApiDomain'

export function useTokenHolder(coin_type?: string) {
  const [holderLoading, setHolderLoading] = useState<boolean>(false)
  const [holderTokenList, setHolderTokenList] = useState<TokenHolder[]>([])
  const { fetchGetByApi } = usePumpApiDomain()

  const fetchTokenHolderList = async (coin_type: string) => {
    const params = new URLSearchParams({ coin_type })
    const api = `${queryTokenHoldersByCoinTypePath}?${params.toString()}`

    try {
      const response = await fetchGetByApi(api)
      const list: TokenHolder[] = response.tokenHolderList

      if (list) {
        setHolderTokenList(list)
      }
      console.log('🚀 ~ file: useTokenHolder.ts:20 ~ fetchTokenHolderList ~ list:', list)
    } catch (error) {
      console.log('🚀 ~ file: useTokenHolder.ts:27 ~ fetchTokenHolderList ~ error:', error)
    }
  }

  useEffect(() => {
    if (coin_type) {
      setHolderLoading(true)
      fetchTokenHolderList(coin_type).finally(() => {
        setHolderLoading(false)
      })
    }
  }, [coin_type])

  return {
    holderTokenList,
    holderLoading,
    fetchTokenHolderList
  }
}
