import Rocket from '@/assets/images/img_rocket@2x.png'
import { useGetPumpToken } from '@/hook/pump/useGetPumpToken'
import { PumpToken } from '@/type/pump'
import Block from '@cetus/design/src/components/common/Block'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import useTransaction from '@cetus/hooks/src/useTransaction'
import { CommonTypeInfo } from '@cetus/types/src/common-types'
import envConfigs from '@cetus/types/src/config/envConfigs'
import { getPackagerConfigs } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { Button, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

type CompletedProps = {
  token?: PumpToken
}

function Completed(props: CompletedProps) {
  const { token } = props
  const [loading, setLoading] = useState(false)
  const { pumpSdk, clmmSdk } = useInitSDK()
  const { signAndExecuteTransaction } = useTransaction()
  const { refreshPumpToken } = useGetPumpToken()

  const doMigrateClick = async () => {
    setLoading(true)
    const { clmm_pool } = clmmSdk.sdkOptions
    const { global_config_id, pools_id } = getPackagerConfigs(clmm_pool)

    try {
      const tx = pumpSdk.pumpModule.buildCompleteBondingCurvePayload({
        bonding_curve_id: token!.token_info_id,
        token_metadata_id: token!.TokenDetail.coin_metadata_id,
        sui_metadata_id: envConfigs.sui_coin.id,
        token_coin_type: token!.TokenDetail.coin_type,
        clmm_global_config_id: global_config_id,
        clmm_pools_id: pools_id
      })

      const res = await signAndExecuteTransaction(tx, {
        getShowInfo: status => {
          const info: CommonTypeInfo = {
            iconUrl: token!.TokenDetail.image,
            toastTitleText: `${token?.TokenDetail.name} Migration`,
            modalTitleText: `Migration`,
            modalDescriptionText: `Liquidity Migration`
          }
          if (status === 'success') {
            info.toastTitleText = `${token?.TokenDetail.name} Migration successful`
            info.modalDescriptionText = `${token?.TokenDetail.name} Migration successful`
          }

          if (status === 'rejected') {
            info.toastTitleText = `Migration failed`
            info.modalDescriptionText = `Migration failed`
          }

          return info
        }
      })

      if (token) {
        refreshPumpToken(token!.TokenDetail.coin_type)
      }
    } catch (error) {
      console.log('🚀 ~ file: Completed.tsx:38 ~ doMigrateClick ~ error:', error)
    } finally {
      setLoading(false)
    }
  }

  return (
    <Block p="16px">
      <VStack mt="16px" gap="40px">
        <VStack gap="0px">
          <Image src={Rocket} w="200px" h="200px" />
          <Text h="32px" lineHeight="32px" fontSize="16px" color="text_caption">
            Completed bonding Curve
          </Text>
        </VStack>
        <HStack mb="44px" p="0 30px" gap="14px" w="100%">
          <Button isLoading={loading} flex="1" fontWeight="500" fontSize="14px" onClick={() => doMigrateClick()}>
            Migrate to Cetus DEX
          </Button>
        </HStack>
      </VStack>
    </Block>
  )
}

export default Completed
