import { d, sleepTime } from '@cetus/utils'

// const apiHost = 'https://api-sui.cetus.zone'

type DataFeedsParams = {
  end_time: number
  symbolAndId: string
  changeLastPrice: any
  timerInput: any
  changeTimer: any
  subscriberUIDRef: any
  changeSubscriberUIDRef: any
  fetchKLineData: (data_type: string, start_timestamp: string, end_timestamp: string, token_info_id: string, ticker: string) => Promise<any>
}

const configurationData = {
  // Represents the resolutions for bars supported by your datafeed
  // supported_resolutions: ['1D', '1W', '1M']
  // supported_resolutions: ['1', '15', '30', '60', '240', 'D', 'W', 'M']
  // supported_resolutions: ['1', '10', '15', '30', '60', '240', 'D', 'W'],
  supported_resolutions: ['1', '5'],
  // The `exchanges` arguments are used for the `searchSymbols` method if a user selects the exchange
  // exchanges: [
  //   { value: 'Bitfinex', name: 'Bitfinex', desc: 'Bitfinex' },
  //   { value: 'Kraken', name: 'Kraken', desc: 'Kraken bitcoin exchange' }
  // ],
  // The `symbols_types` arguments are used for the `searchSymbols` method if a user selects this symbol type
  // symbols_types: [
  //   { name: 'crypto', value: 'crypto' }
  // ]
  supports_time: true
}

// const dateType: any = {
//   '1': '1min',
//   '10': '10min',
//   '15': '15min',
//   '30': '30min',
//   '60': 'hour',
//   '240': '4hour',
//   '1D': 'day',
//   '1W': 'week'
// }
const dateType: any = {
  '1': 60,
  '5': 300
}

// const secondObj: any = {
//   '1': 60,
//   '10': 60 * 10,
//   '15': 60 * 15,
//   '30': 60 * 30,
//   '60': 60 * 60,
//   '240': 240 * 60,
//   '1D': 24 * 60 * 60,
//   '1W': 7 * 24 * 60 * 60
// }
const secondObj: any = {
  '1': 60,
  '5': 60 * 5
}

class DataFeeds {
  changeLastPrice: any
  timer: any
  liveDataObjs: any
  changeTimer: any
  symbolAndId: string

  _subscriberUID: any
  changeSubscriberUIDRef: any
  end_time: number

  fetchKLineData: (data_type: string, start_timestamp: string, end_timestamp: string, token_info_id: string, ticker: string) => Promise<any>

  constructor({
    symbolAndId,
    changeLastPrice,
    timerInput,
    changeTimer,
    subscriberUIDRef,
    changeSubscriberUIDRef,
    fetchKLineData,
    end_time
  }: DataFeedsParams) {
    this.changeLastPrice = changeLastPrice
    this.timer = timerInput
    this.liveDataObjs = {
      '1': {},
      '10': {},
      '15': {},
      '30': {},
      '60': {},
      '240': {},
      '1D': {},
      '1W': {}
    }
    this.changeTimer = changeTimer
    this.symbolAndId = symbolAndId
    this._subscriberUID = subscriberUIDRef
    this.changeSubscriberUIDRef = changeSubscriberUIDRef
    this.fetchKLineData = fetchKLineData
    this.end_time = end_time
  }

  onReady(callback: any) {
    console.log('datafeed###[onReady]: Method call')
    setTimeout(() => callback(configurationData))
  }

  searchSymbols(userInput: any, exchange: any, symbolType: any, onResultReadyCallback: any) {
    console.log('datafeed###[searchSymbols]: Method call')
  }

  resolveSymbol(symbolName: any, onSymbolResolvedCallback: any, onResolveErrorCallback: any, extension: any) {
    console.log('datafeed###[resolveSymbol]: symbolName', symbolName)
    console.log('datafeed###[resolveSymbol]: extension', extension)
    const arr = symbolName?.split('::')
    const symbol = arr[0]
    let id = arr[1]
    console.log('datafeed###[resolveSymbol]:symbol####', symbol)
    console.log('datafeed###[resolveSymbol]:id####', id)

    if (!id) {
      const originSymbolAndIdArr = this.symbolAndId?.split('::')
      if (originSymbolAndIdArr?.[0] === symbol && originSymbolAndIdArr?.[1]) {
        id = originSymbolAndIdArr?.[1]
      }
    }

    // if (!id) return
    // Symbol information object
    const symbolInfo = {
      ticker: symbol,
      name: symbol,
      description: symbol,
      id,
      // type: 'test type',
      session: '24x7',
      timezone: 'Etc/UTC',
      // exchange: 'test exchange',
      minmov: 1,
      pricescale: 100000000000, //控制小数位
      has_intraday: true,
      // visible_plots_set: 'ohlc',
      has_weekly_and_monthly: true,
      supported_resolutions: configurationData.supported_resolutions,
      volume_precision: 2,
      symbolAndId: symbolName
      // data_status: 'streaming'
    }

    onSymbolResolvedCallback(symbolInfo)
  }

  async getBars(symbolInfo: any, resolution: any, periodParams: any, onHistoryCallback: any, onErrorCallback: any) {
    const { from, to, firstDataRequest, countBack } = periodParams

    console.log('🚀 ~ file: datafeed.ts:161 ~ DataFeeds ~ getBars ~ periodParams:', periodParams)

    const type = dateType[resolution]

    let fromTime = from
    let toTime = to

    // 如果指定了截止时间，则初始化获取当前时间之前的300条数据
    if (this.end_time > 0 && firstDataRequest) {
      toTime = this.end_time
      fromTime = d(toTime)
        .minus(Number(resolution) * 60 * 300)
        .toFixed(0)
    }

    // const { id } = symbolInfo
    const id = symbolInfo.id
    const symbol = symbolInfo.ticker
    console.log('datafeed###[getBars]: from', fromTime)
    console.log('datafeed###[getBars]: to', toTime)

    const barsArr: any = []

    const res: any = await this.fetchKLineData(type, fromTime, toTime, id, symbol)

    console.log('datafeed###getPrice###res###', res)
    const list = res?.lists || []
    if (list?.length > 0) {
      list.forEach((item: any) => {
        barsArr.push({
          high: Number(item.high),
          low: Number(item.low),
          open: Number(item.open),
          close: Number(item.settle),
          time: d(item.timestamp).mul(1000).toNumber()
        })
      })
    }

    console.log('datafeed###getPrice###barsArr###', barsArr)

    if (barsArr?.length > 0) {
      onHistoryCallback(barsArr, { noData: false })
    } else {
      onHistoryCallback(barsArr, { noData: true })
    }
  }
  async subscribeBars(symbolInfo: any, resolution: any, onRealtimeCallback: any, subscriberUID: any, onResetCacheNeededCallback: any) {
    // 如果指定了截止时间，则不需要进行增量更新
    if (this.end_time > 0) {
      if (this.timer) {
        clearInterval(this.timer)
        this.timer = null
        this.changeTimer(null)
      }
      return
    }
    console.log('datafeed###[subscribeBars]: Method call with subscriberUID:', subscriberUID)
    console.log('datafeed###[subscribeBars]: symbolInfo:', symbolInfo)
    console.log('datafeed###[subscribeBars]: symbolInfo.id:', symbolInfo.id)
    console.log('datafeed###[subscribeBars]: resolution:', resolution)

    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
      this.changeTimer(null)
    }

    await sleepTime(1000)
    const params = {
      // symbolInfo,
      id: symbolInfo.id,
      resolution,
      symbol: symbolInfo.ticker
    }

    // console.log('this.timer')

    this.timer = setInterval(async () => {
      const type = dateType[params.resolution]
      const step = secondObj[params.resolution]
      const now = new Date().getTime()
      const to = d(now).div(1000).floor().toNumber()
      const from = d(to).minus(step).toNumber()
      const id = params.id
      const symbol = params.symbol

      const res: any = await this.fetchKLineData(type, from.toString(), to.toString(), id, symbol)

      const list = res?.lists || []
      console.log('0117###subscribeBars###list###', list)

      const data = list?.[list.length - 1]
      if (data) {
        const info = {
          high: Number(data?.high),
          low: Number(data?.low),
          open: Number(data?.open),
          close: Number(data?.settle),
          time: d(data.timestamp).mul(1000).toNumber()
        }

        this.changeLastPrice({
          id,
          price: data?.settle || ''
        })

        onRealtimeCallback({ ...info })
      }
    }, 10000)

    this.changeTimer(this.timer)
  }

  unsubscribeBars(subscriberUID: any) {
    console.log('datafeed###[unsubscribeBars]: Method call with subscriberUID:', subscriberUID)
    clearInterval(this.timer)
    this.timer = null
    this.changeTimer(null)
  }
}

export default DataFeeds
